// Topic layers — the S-03 reference-architecture view over the room archive (E-10 item 3 /
// YED-126). The committed src/data/topic-layers.json is generated by scripts/gen-topic-layers.mjs
// from the pipeline repo's topic→layer map (joined with its topics snapshot, so entries are keyed
// by name). Parsed at import, so a malformed export — or drift from the S-03 layer ids — fails
// the build instead of rendering something wrong. No graph access here by design: public pages
// read only the committed, reviewed JSON.
//
// duplicate_of is absent from the data on purpose: it is a proposal awaiting Alex's ruling, and
// nothing here may collapse or dedupe topics on it.
import { z } from "zod";
import TOPIC_LAYERS_JSON from "@/data/topic-layers.json";
import { getRooms } from "@/lib/rooms";

const LAYER_IDS = [
  "model",
  "environment",
  "harness",
  "factory",
  "data-retrieval",
  "evals-observability",
  "identity-governance",
  "gtm-distribution",
  "domain-applications",
  "market-context",
] as const;

// Presentation metadata — labels and the one-line definitions from the pipeline's
// .claude/references/reference-architecture.md, in architecture order.
const LAYER_META: Record<(typeof LAYER_IDS)[number], { label: string; description: string }> = {
  model: {
    label: "Model",
    description: "Foundation models and what happens inside them: releases, reasoning, training, model economics.",
  },
  environment: {
    label: "Environment",
    description: "Where agents and AI workloads run: clouds, GPUs and custom silicon, sandboxes, serving infrastructure.",
  },
  harness: {
    label: "Harness",
    description: "The scaffolding around models: agent frameworks, orchestration, MCP, context engineering, coding agents.",
  },
  factory: {
    label: "Factory",
    description: "How software is designed, built, reviewed and shipped when agents do the building.",
  },
  "data-retrieval": {
    label: "Data & Retrieval",
    description: "Getting the right context to models: data infrastructure, RAG, vector search, the modern data stack.",
  },
  "evals-observability": {
    label: "Evals & Observability",
    description: "Knowing whether AI works: evaluation suites, tracing, reliability engineering and production failure modes.",
  },
  "identity-governance": {
    label: "Identity & Governance",
    description: "Who agents are and what they may do: identity, auth, security, compliance, governance and trust.",
  },
  "gtm-distribution": {
    label: "GTM & Distribution",
    description: "How AI products reach and monetize customers: sales, marketing, pricing, RevOps and distribution strategy.",
  },
  "domain-applications": {
    label: "Domain Applications",
    description: "Agents applied in a specific domain or industry: vertical SaaS, healthcare, fintech, legal, media, robotics.",
  },
  "market-context": {
    label: "Market Context",
    description: "The surrounding landscape: capital flows, talent markets, policy and geopolitics, ecosystem structure.",
  },
};

const TopicLayerSchema = z.object({
  id: z.string().uuid(),
  name: z.string().min(1),
  layer: z.enum(LAYER_IDS),
  secondary: z.enum(LAYER_IDS).optional(),
});

const FILE = z
  .object({
    generatedAt: z.iso.datetime(),
    source: z.object({
      repo: z.string().min(1),
      commit: z.string().min(1),
      paths: z.array(z.string()).min(1),
      asOf: z.string().min(1),
    }),
    topics: z.array(TopicLayerSchema),
  })
  .parse(TOPIC_LAYERS_JSON);

function assertIntegrity(topics: z.infer<typeof TopicLayerSchema>[]): void {
  const ids = new Set<string>();
  const names = new Set<string>();
  for (const t of topics) {
    if (ids.has(t.id)) throw new Error(`topic-layers.json: duplicate topic id "${t.id}"`);
    if (names.has(t.name)) throw new Error(`topic-layers.json: duplicate topic name "${t.name}"`);
    ids.add(t.id);
    names.add(t.name);
    if (t.secondary && t.secondary === t.layer) {
      throw new Error(`topic-layers.json: "${t.name}" has secondary equal to layer`);
    }
  }
}

assertIntegrity(FILE.topics);

const BY_NAME = new Map(FILE.topics.map((t) => [t.name, t]));

export type LayerView = {
  id: (typeof LAYER_IDS)[number];
  label: string;
  description: string;
  /** Rooms carrying at least one topic whose PRIMARY layer is this one. */
  rooms: { slug: string; name: string }[];
  roomCount: number;
  /** Distinct room-carried topics whose primary layer is this one. */
  topicCount: number;
  /** Rooms whose carried topics touch this layer only as a secondary assignment. */
  secondaryRoomCount: number;
};

export function getLayers(): LayerView[] {
  const rooms = getRooms();
  const primary = new Map<string, { rooms: Set<string>; topics: Set<string> }>(LAYER_IDS.map((id) => [id, { rooms: new Set(), topics: new Set() }]));
  const secondary = new Map<string, Set<string>>(LAYER_IDS.map((id) => [id, new Set()]));

  for (const room of rooms) {
    for (const name of room.topics ?? []) {
      const topic = BY_NAME.get(name);
      if (!topic) continue; // unmapped room topic — counted in layerCoverage(), not silently merged in
      primary.get(topic.layer)!.rooms.add(room.slug);
      primary.get(topic.layer)!.topics.add(name);
      if (topic.secondary) secondary.get(topic.secondary)!.add(room.slug);
    }
  }

  const views = LAYER_IDS.map((id) => ({
    id,
    label: LAYER_META[id].label,
    description: LAYER_META[id].description,
    rooms: rooms
      .filter((r) => primary.get(id)!.rooms.has(r.slug))
      .map((r) => ({ slug: r.slug, name: r.name })),
    roomCount: primary.get(id)!.rooms.size,
    topicCount: primary.get(id)!.topics.size,
    secondaryRoomCount: secondary.get(id)!.size,
  }));

  // Signal-density order: most rooms first, architecture order as the tiebreak.
  return views.sort((a, b) => b.roomCount - a.roomCount || LAYER_IDS.indexOf(a.id) - LAYER_IDS.indexOf(b.id));
}

/**
 * How much of the room archive's topic vocabulary the S-03 map covers. Room topic names and
 * graph topic names are two exports of the same Notion vocabulary; where they drift, the room
 * topics are excluded from layer counts and the gap is stated on the page instead of hidden.
 */
export function layerCoverage(): { mappedTopics: number; totalRoomTopics: number; source: typeof FILE.source } {
  const roomTopicNames = new Set(getRooms().flatMap((r) => r.topics ?? []));
  const mapped = [...roomTopicNames].filter((name) => BY_NAME.has(name)).length;
  return { mappedTopics: mapped, totalRoomTopics: roomTopicNames.size, source: FILE.source };
}
